package cn.yulin.english;
import android.app.*;import android.content.*;import android.media.*;import android.net.Uri;import android.os.*;import android.widget.*;import android.view.View;import java.util.Locale;
/** Foreground-only playback, content URIs and app-private downloaded files. */
public final class AudioPlayer {
 private final Activity activity;private final Handler handler=new Handler(Looper.getMainLooper());private MediaPlayer player;private AlertDialog dialog;private boolean ready;private SeekBar seek;private TextView time;private Button toggle;private AudioManager audio;private AudioFocusRequest focus;
 public AudioPlayer(Activity activity){this.activity=activity;audio=(AudioManager)activity.getSystemService(Context.AUDIO_SERVICE);}
 private String stamp(int ms){return String.format(Locale.ROOT,"%d:%02d",ms/60000,ms/1000%60);}
 private void toast(String s){Toast.makeText(activity,s,Toast.LENGTH_LONG).show();}
 public void play(Uri uri,String title){stop();LinearLayout box=new LinearLayout(activity);box.setOrientation(1);box.setPadding(28,20,28,20);time=new TextView(activity);time.setText("正在加载录音…");box.addView(time);seek=new SeekBar(activity);seek.setEnabled(false);box.addView(seek);LinearLayout controls=new LinearLayout(activity);Button back=new Button(activity);back.setText("后退 10 秒");toggle=new Button(activity);toggle.setText("播放");toggle.setEnabled(false);Button next=new Button(activity);next.setText("前进 10 秒");controls.addView(back);controls.addView(toggle);controls.addView(next);box.addView(controls);Spinner speed=new Spinner(activity);speed.setAdapter(new ArrayAdapter<String>(activity,android.R.layout.simple_spinner_dropdown_item,new String[]{"0.75 倍","1.0 倍（原速）","1.25 倍","1.5 倍"}));speed.setSelection(1);box.addView(speed);TextView note=new TextView(activity);note.setText("原速播放不会改变录音的口音。离开应用时暂停，返回后可继续。");box.addView(note);dialog=new AlertDialog.Builder(activity).setTitle(title).setView(box).setNegativeButton("关闭",(d,w)->stop()).create();dialog.setOnCancelListener(d->stop());dialog.show();
  player=new MediaPlayer();final MediaPlayer current=player;current.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build());
  current.setOnPreparedListener(mp->{if(player!=mp)return;ready=true;seek.setEnabled(true);seek.setMax(mp.getDuration());toggle.setEnabled(true);start();tick();});current.setOnCompletionListener(mp->{if(player==mp){toggle.setText("重播");if(focus!=null)audio.abandonAudioFocusRequest(focus);}});current.setOnErrorListener((mp,what,extra)->{if(player==mp){ready=false;if(focus!=null)audio.abandonAudioFocusRequest(focus);toggle.setEnabled(false);time.setText("此录音无法解码或文件已损坏。旧 WMA/WAV 请下载云端转换后的 MP3，或检查原文件。");}return true;});
  try{current.setDataSource(activity,uri);current.prepareAsync();}catch(Exception e){time.setText("无法读取此录音，请重新选择原文件夹或重新下载。");}
  toggle.setOnClickListener(v->{if(!ready)return;if(player.isPlaying())pause();else start();});back.setOnClickListener(v->{if(ready)player.seekTo(Math.max(0,player.getCurrentPosition()-10000));});next.setOnClickListener(v->{if(ready)player.seekTo(Math.min(player.getDuration(),player.getCurrentPosition()+10000));});seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int value,boolean user){if(user&&ready)player.seekTo(value);}});
  speed.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int position,long id){if(ready)try{boolean playing=player.isPlaying();player.setPlaybackParams(new PlaybackParams().setSpeed(new float[]{.75f,1f,1.25f,1.5f}[position]).setPitch(1f));if(!playing)player.pause();}catch(Exception e){toast("当前设备不支持此倍速，继续使用原速。");}}});
 }
 private void start(){if(!ready)return;focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build()).setOnAudioFocusChangeListener(change->{if(change<0)pause();}).build();if(audio.requestAudioFocus(focus)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED){toast("其他应用正在使用声音，请稍后再试。");return;}player.start();toggle.setText("暂停");}
 private final Runnable pulse=()->tick();private void tick(){if(ready&&player!=null){seek.setProgress(player.getCurrentPosition());time.setText(stamp(player.getCurrentPosition())+" / "+stamp(player.getDuration()));handler.postDelayed(pulse,500);}}
 public void pause(){if(ready&&player!=null&&player.isPlaying()){player.pause();toggle.setText("继续播放");}if(focus!=null)audio.abandonAudioFocusRequest(focus);}
 public void stop(){handler.removeCallbacksAndMessages(null);ready=false;if(player!=null){player.release();player=null;}if(focus!=null){audio.abandonAudioFocusRequest(focus);focus=null;}if(dialog!=null){dialog.setOnCancelListener(null);dialog.dismiss();dialog=null;}}
}
